it('rechecks Archive documents after executor output and before committing the outcome', async () => {
    await expect(
      awaitingArchiveApplication('memory', () => {
        const execute = nativeSdkArchivePreflightExecutor.execute;
        vi.spyOn(nativeSdkArchivePreflightExecutor, 'execute').mockImplementation(
          async (action, context, run) => {
            const output = await execute(action, context, run);
            const paths = await nativeProjectPaths(context!.projectRoot!, 'docs');
            const brief = path.join(paths.changesDir, 'sdk-shape', 'brief.md');
            await fs.writeFile(
              brief,
              (await fs.readFile(brief, 'utf8')).replace(
                'The selected workflow resumes.',
                'The selected workflow changed after preflight.',
              ),
            );
            return output;
          },
        );
      }),
    ).rejects.toThrow(/OUTCOME_REJECTED/u);
  });

it('does not enter Build when Shape documents change after approval', async () => {
    const { root, paths, changeDir, runtime, run: prepared } = await preparedShape();
    const wait = prepared.waits.at(-1)!;
    const approved = await runtime.resolveWait({
      runId: prepared.runId,
      waitId: wait.id,
      proposalHash: wait.proposalHash,
      decisionId: 'shape-approved',
      choice: 'approved',
    });
    const briefFile = path.join(changeDir, 'brief.md');
    const brief = await fs.readFile(briefFile, 'utf8');
    await fs.writeFile(
      briefFile,
      brief.replace('Preserve the selected workflow.', 'Preserve a different workflow.'),
    );
    await expect(
      succeedLatestAction(
        runtime,
        approved,
        await collectProposal(paths, approved.state as NativePortableState),
        root,
        'shape-stale',
      ),
    ).rejects.toThrow(/OUTCOME_REJECTED/);
    const current = await runtime.inspect(approved.runId);
    expect(current.state).toMatchObject({ phase: 'shape', status: 'await-user' });
    expect(current.actions.some((action) => action.stepId === 'build.builder')).toBe(false);
  });

it('rejects candidate drift before v3 Archive publication after merging the revalidation Action', async () => {
  const prepared = await dispatchedVerifier(
    [],
    'sdk',
    nativeApplication('3'),
    true,
    undefined,
    async (root) => {
      await fs.writeFile(path.join(root, 'implementation.js'), 'export const value = true;');
    },
  );
  const { root, runtime, paths } = prepared;
  const state = prepared.run.state as NativePortableState;
  const run = await succeedLatestAction(
    runtime,
    prepared.run,
    {
      candidateId: state.builder_handoff!.candidate_id,
      verifierExecutionRef: 'v3-drift-verifier',
      response: {
        kind: 'final-result',
        result: {
          iteration: state.loop.iteration,
          attempt: state.loop.attempt,
          verdict: 'pass',
          acceptance: [{ id: 'A1', result: 'passed', reason: 'Verified original implementation.' }],
          risks: [],
          summary: 'Original candidate passed.',
        },
      },
    },
    root,
    'v3-drift-result',
    'v3-drift-verifier',
  );
  await fs.writeFile(path.join(root, 'implementation.js'), 'export const value = false;');
  const wait = run.waits.at(-1)!;
  await runtime.resolveWait({
    runId: run.runId,
    waitId: wait.id,
    proposalHash: wait.proposalHash,
    decisionId: 'v3-drift-approved',
    choice: 'approved',
  });
  const archived = await runNativeCli(['archive', run.runId, '--project-root', root, '--json']);
  expect(archived.exitCode).toBe(73);
  expect((await runtime.inspect(run.runId)).state).toMatchObject({
    phase: 'verify',
    verification_result: 'pending',
  });
  expect(
    await fs.stat(path.join(paths.specsDir, 'workflow', 'spec.md')).catch(() => null),
  ).toBeNull();
});

it('recovers a rejected Builder after formal Spec drift through the original failure receipt and reconfirms the same change', async () => {
    const f = await builderFixture();
    await cli(f.root, f.requestFile);
    const before = await inspectNativeSdkRun(f.root, f.name);
    const spec = path.join(f.root, 'docs/comet/changes', f.name, 'specs/workflow/spec.md');
    await fs.writeFile(spec, '# Workflow\nThe workflow resumes and records an audit event.\n');
    await fs.writeFile(
      f.requestFile,
      JSON.stringify({
        operation: 'record-outcome',
        runId: f.name,
        outcome: {
          actionId: f.request.actionId,
          attempt: f.request.attempt,
          inputHash: f.request.inputHash,
          claimToken: f.request.claimToken,
          outcomeId: 'rejected-candidate',
          status: 'succeeded',
          output: {
            summary: 'Implemented the fixture.',
            addressedAcceptanceIds: ['A1'],
            acceptanceReview: fixtureAcceptanceReview(['A1']),
            checks: [],
            knownLimits: [],
            review: null,
            submittedAt: new Date().toISOString(),
            verificationChecks: [],
          },
        },
      }),
    );
    const rejected = await runtimeDispatchCommand(
      { application: 'native', projectRoot: f.root, request: f.requestFile },
      { output: 'compact' },
    );
    expect(rejected.response.status).toBe('failed');
    const recovery = rejected.response.recovery as {
      code: string;
      affectedPaths: string[];
      request: { outcome: { actionId: string; claimToken: string; status: string } };
      recoveryArgs: string[];
    };
    expect(recovery).toMatchObject({
      code: 'shape-drift',
      affectedPaths: [spec],
      request: {
        operation: 'record-outcome',
        runId: f.name,
        outcome: {
          actionId: f.request.actionId,
          claimToken: f.request.claimToken,
          status: 'failed',
        },
      },
    });
    const rejectedRun = (await inspectNativeSdkRun(f.root, f.name)).run;
    expect(rejectedRun.state).toEqual(before.run.state);
    expect(rejectedRun.actions.map(({ id }) => id)).toEqual(before.run.actions.map(({ id }) => id));
    expect(rejectedRun.actions.find(({ id }) => id === f.request.actionId)).toMatchObject({
      status: 'running',
      claim: { token: f.request.claimToken },
      rejectedOutcomes: [{ code: 'OUTCOME_REJECTED' }],
    });
    await fs.writeFile(f.requestFile, JSON.stringify(recovery.request));
    const previousExitCode = process.exitCode;
    const logged = vi.spyOn(console, 'log').mockImplementation(() => undefined);
    try {
      await runRuntimeCli(
        recovery.recoveryArgs
          .slice(1)
          .map((arg) => (arg === '<failure-outcome-request-json-file>' ? f.requestFile : arg)),
      );
      expect(process.exitCode, JSON.stringify(logged.mock.calls)).toBe(0);
    } finally {
      logged.mockRestore();
      process.exitCode = previousExitCode;
    }
    const once = (await inspectNativeSdkRun(f.root, f.name)).run;
    expect(
      (
        await runtimeDispatchCommand({
          application: 'native',
          projectRoot: f.root,
          request: f.requestFile,
        })
      ).response.status,
    ).toBe('succeeded');
    expect((await inspectNativeSdkRun(f.root, f.name)).run).toEqual(once);
    const status = JSON.parse(
      (await runNativeCli(['status', f.name, '--project-root', f.root, '--json'])).stdout!,
    );
    const revise = status.data.continuation.commandAlternatives.find(
      (entry: { name: string }) => entry.name === 'revise-requirements',
    );
    expect(revise).toBeDefined();
    const args = revise.commandArgs
      .slice(2)
      .map((arg: string) =>
        arg === '<summary>' ? 'The user explicitly requests reconfirming the edited Spec.' : arg,
      );
    const revised = await runNativeCli(args);
    expect(revised.exitCode, revised.stdout || revised.stderr).toBe(0);
    const after = await inspectNativeSdkRun(f.root, f.name);
    expect(after.run.runId).toBe(before.run.runId);
    expect(after.state.phase).toBe('shape');
    expect(after.state.archived).toBe(false);
    expect(after.run.actions.find(({ id }) => id === f.request.actionId)?.status).toBe('failed');
  });

it('lists workspace candidates instead of choosing when several packages build', async () => {
    const dir = await makeProject();
    const cli = (...args: string[]) =>
      withClassicCommandContext({ projectRoot: dir, invocationCwd: dir }, () =>
        runClassicCli(args),
      );
    expect(
      (
        await cli(
          'state',
          'init',
          'demo',
          'hotfix',
          '--isolation',
          'current',
          '--runtime',
          'compat',
        )
      ).exitCode,
    ).toBe(0);
    const changeDir = path.join(dir, 'openspec/changes/demo');
    const stateFile = path.join(changeDir, '.comet.yaml');
    const state = parse(await fs.readFile(stateFile, 'utf8'));
    await fs.writeFile(stateFile, stringify({ ...state, phase: 'build' }));
    await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] work <!-- comet-task:a -->\n');
    await fs.writeFile(path.join(changeDir, 'proposal.md'), '# Proposal\n');
    await fs.writeFile(
      path.join(dir, 'package.json'),
      JSON.stringify({ name: 'root', private: true, workspaces: ['packages/*'] }),
    );
    for (const name of ['app', 'lib']) {
      await fs.mkdir(path.join(dir, 'packages', name), { recursive: true });
      await fs.writeFile(
        path.join(dir, 'packages', name, 'package.json'),
        JSON.stringify({ name, scripts: { build: 'node -e "process.exit(0)"' } }),
      );
    }
    const result = await cli('guard', 'demo', 'build');
    expect(result.exitCode, result.stderr).toBe(1);
    expect(result.stderr).toContain('several workspace packages declare one');
    expect(result.stderr).toContain('packages/app, packages/lib');
    expect(result.stderr).toContain('npm --prefix packages/app run build');
  });
